INSERT INTO "miner_fundamentals" (
  "symbol", "name", "primary_metal", "jurisdiction", "project_stage", "production_oz", "aisc_usd_per_oz", "resource_moz", "reserve_moz", "cash_aud", "debt_aud", "market_cap_aud", "npv_aud", "capex_aud", "irr_percent", "jurisdiction_score", "balance_sheet_score", "dilution_score", "management_score", "notes", "source_url", "as_of_date", "updated_at"
) VALUES
  ('AG', 'First Majestic Silver Corp.', 'Silver / gold', 'Mexico, United States', 'Producer', 3799823, 25.68, NULL, NULL, 1531275980, NULL, NULL, NULL, NULL, NULL, 3, 4, 3, 3, 'Q2 2026 silver production and AISC are latest reported quarter metrics, not annualized. Cash is Q2 2026 cash and equivalents converted at ~US$1=A$1.40. Scores are SouthernStar judgement inputs; key risks are Mexico operating exposure, multi-asset execution and capital allocation after the Los Gatos transaction.', 'https://firstmajestic.com/investors/news-releases/first-majestic-announces-q2-2026-financial-results-and-quarterly-dividend-payment', '2026-06-30'::date, NOW()),
  ('ASL', 'Andean Silver Limited', 'Silver / gold', 'Chile', 'Developer / explorer', NULL, NULL, 136, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, 3, 2, 3, 'Company-reported Cerro Bayo silver-equivalent mineral resource as at 30 June 2026. Developer-stage record intentionally leaves production, AISC, reserve and project economics blank until a current technical/economic study is available. Scores are SouthernStar judgement inputs.', 'https://www.andeansilver.com/cerro-bayo-project/', '2026-06-30'::date, NOW()),
  ('ASM', 'Avino Silver & Gold Mines Ltd.', 'Silver / gold / copper', 'Mexico', 'Producer / development ramp', 1157828, 23.75, NULL, 127, 142474634, NULL, NULL, NULL, NULL, NULL, 3, 4, 3, 3, 'FY2025 silver production, FY2025 AgEq AISC and year-end cash are company-reported. Reserve field uses April 2026 inaugural proven and probable silver-equivalent reserve because the latest source reports 127 Moz AgEq rather than only silver ounces. Current holding is marked residual/zero value, so broker position should be checked separately.', 'https://www.avino.com/news/avino-announces-q2-2026-production-results', '2026-06-30'::date, NOW()),
  ('AYA', 'Aya Gold & Silver Inc.', 'Silver', 'Morocco', 'Producer / expansion', 5000000, NULL, 104.75, 73.39, 256309800, NULL, NULL, NULL, NULL, NULL, 3, 4, 3, 3, 'Existing Zgounder reserve/resource base retained. Q2 2026 update reported record 1.7 Moz AgEq consolidated production and US$183M cash; cash converted at ~US$1=A$1.40. Production field remains the previously sourced annual silver figure to avoid mixing quarterly output into annual fields. Scores are SouthernStar judgement inputs.', 'https://ayagoldsilver.com/news/news-releases/aya-gold--silver-reports-q2-2026-results-and-delivers-record-operational-performance', '2026-06-30'::date, NOW()),
  ('BMN', 'Bannerman Energy Ltd.', 'Uranium', 'Namibia', 'Developer / construction readiness', NULL, 39.09, NULL, NULL, 53100000, 0, NULL, 546234000, 494411800, 21.1, 4, 3, 3, 3, 'Etango-8 DFS/FEED metrics use uranium lb units despite the app label saying oz: AISC US$/lb U3O8, NPV8 US$390M, pre-production capex US$353M and post-tax IRR 21.1%. Cash is 30 Jun 2026 cash only; company also reported SPUT and Namibia Critical Metals liquid assets. No debt reported. Funding remains the gating risk until CNOL/JV and FID complete.', 'https://bannermanenergy.com/project-economics/', '2026-06-30'::date, NOW()),
  ('CCJ', 'Cameco Corp.', 'Uranium / nuclear fuel services', 'Canada, Kazakhstan, United States', 'Producer / nuclear fuel cycle', 20500000, NULL, NULL, NULL, 1118700000, 1017000000, NULL, NULL, NULL, NULL, 4, 4, 4, 4, 'Production field is midpoint of unchanged 2026 uranium production guidance of 19.5-21.5 Mlb U3O8 attributable share. Cash and debt are 30 Jun 2026 Canadian-dollar figures converted at ~C$1=A$1.017. AISC/resource/reserve fields left blank here because the source used for this update was the Q2 operating report, not a reserve table.', 'https://www.cameco.com/invest/financial-information/quarterly-reports/2026/q2', '2026-06-30'::date, NOW()),
  ('CDE', 'Coeur Mining Inc.', 'Silver / gold / copper', 'United States, Mexico, Canada', 'Producer', 17900000, NULL, 313.8, 274.4, 1473851380, 987843180, NULL, NULL, NULL, NULL, 4, 4, 3, 3, '2025 silver production and year-end silver reserve/resource base retained from company reserve reporting. Q2 2026 update adds cash, equivalents and short-term investments plus total debt, converted at ~US$1=A$1.40. AISC remains blank because the current release reports adjusted CAS rather than full AISC by silver ounce. Scores are SouthernStar judgement inputs.', 'https://www.coeur.com/investors/news/news-details/2026/Coeur-Reports-Second-Quarter-2026-Results/default.aspx', '2026-06-30'::date, NOW()),
  ('DYL', 'Deep Yellow Limited', 'Uranium', 'Namibia, Australia', 'Developer', NULL, NULL, 137, 79.5, NULL, NULL, NULL, 838200000, NULL, 27, 4, 3, 2, 3, 'Tumas resource/reserve fields use Mlb U3O8 despite the app label saying Moz. NPV and IRR are from the Tumas DFS review/re-costing summary. Capex and AISC are left blank until the current re-costing table is captured directly. Developer-stage funding and schedule risk remain the main watch items.', 'https://deepyellow.com.au/projects/namibia/tumas-project/', '2026-06-30'::date, NOW()),
  ('ETPMAG', 'Global X Physical Silver Structured', 'Physical silver', 'Australia / JPMorgan custody structure', 'Physical metal ETC', NULL, NULL, NULL, NULL, NULL, NULL, 1424491341, NULL, NULL, NULL, 4, 5, 5, 4, 'This is a physically backed silver product, not a miner. Market cap field is used as AUM because that is the relevant fund-scale metric. Mine production, AISC, resources and reserves are intentionally blank. The current classifier shows it in the miner workbench because of the silver label; review sector classification separately if it should stay with bullion instead.', 'https://www.globalxetfs.com.au/funds/', '2026-08-20'::date, NOW()),
  ('GDX', 'VanEck Gold Miners ETF', 'Gold miners ETF', 'Global', 'ETF', NULL, NULL, NULL, NULL, NULL, NULL, 31950361777, NULL, NULL, NULL, 4, 3, 4, 4, 'ETF record: operating mine economics do not apply at fund level. AUM is derived from VanEck holdings disclosure where Newmont was 10.66% of net assets with US$2.4317B market value. Top exposures included Newmont, Agnico Eagle, Barrick, Wheaton, AngloGold and Franco-Nevada. Scores reflect diversified fund structure, not a single issuer.', 'https://www.vaneck.com/us/en/investments/gold-miners-etf-gdx/overview/?redirectVE=generic', '2026-07-14'::date, NOW()),
  ('HL', 'Hecla Mining Company', 'Silver / gold / base metals', 'United States, Canada', 'Producer', 17000000, 11.28, 629, 231, 823552800, 0, NULL, NULL, NULL, NULL, 5, 5, 4, 4, '2025 production, AISC and reserves/resources are company-reported. Resource field combines measured/indicated and inferred silver resources because the app has one resource field. Cash is Q1 2026 and debt is set to zero because the Q1 update says the remaining senior notes were redeemed after quarter end, leaving no long-term debt. Scores are SouthernStar judgement inputs.', 'https://www.hecla.com/investors/why-hecla', '2026-03-31'::date, NOW()),
  ('KGC', 'Kinross Gold Corporation', 'Gold', 'United States, Brazil, Chile, Mauritania, Canada', 'Producer', 2012106, 1821, 44.132, 20.942, 3781620000, NULL, NULL, NULL, NULL, NULL, 4, 5, 4, 4, 'FY2025 attributable gold-equivalent production and year-end reserve/resource base paired with Q2 2026 AISC and cash. Cash converted at ~US$1=A$1.40; debt field left blank because the Q2 source reports net cash rather than gross debt in the summary. Current holding is marked residual/zero value, so broker position should be checked separately.', 'https://www.kinross.com/English/news-and-investors/news-releases/press-release-details/2026/Kinross-reports-strong-2026-second-quarter-results/default.aspx', '2026-06-30'::date, NOW()),
  ('MAG', 'MAG Silver Corp.', 'Silver / gold / zinc / lead', 'Mexico', 'Acquired / corporate action review', 2495000, -3.18, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, 3, 1, 2, 'MAG was acquired by Pan American Silver in 2025. Production and AISC fields use Pan American-reported attributable Juanicipio 2024 silver production and AISC, not MAG standalone current reporting. This record is primarily a risk flag to verify whether the broker holding reflects a stale/corporate-action position.', 'https://panamericansilver.com/operations/silver-segment/juanicipio/', '2025-09-04'::date, NOW()),
  ('NEM', 'Newmont Corporation', 'Gold / copper / silver', 'United States, Australia, Canada, PNG, Ghana, Latin America', 'Producer', NULL, 1621, 148.7, 118.2, 8683720000, NULL, NULL, NULL, NULL, NULL, 4, 5, 4, 4, 'Reserve/resource fields are attributable gold ounces as at year-end 2025; resource combines measured/indicated and inferred gold resources because the app has one resource field. Q2 2026 AISC and cash are from Newmont quarterly reporting, converted at ~US$1=A$1.40. Debt is left blank because the source summary reports liquidity/net leverage rather than gross debt.', 'https://investors.newmont.com/investors/news-release/news-details/2026/Newmont-Reports-2025-Mineral-Reserves-of-118-2-Million-Gold-Ounces-and-12.5-Million-Tonnes-of-Copper/default.aspx', '2026-06-30'::date, NOW()),
  ('NST', 'Northern Star Resources Ltd.', 'Gold', 'Australia, United States', 'Producer', 1540000, 1926, 88.9, 28.4, 1200000000, NULL, NULL, NULL, NULL, NULL, 4, 5, 4, 4, 'FY2026 gold sales, AISC, cash/bullion and resources/reserves are company-reported. AISC was reported in A$/oz and converted to US$/oz at ~US$1=A$1.40 for the app field. Debt is left blank because the source excerpt gives cash/bullion and liquidity context, not gross debt.', 'https://financialfilings.com/filings/northern-star-resources-ltd/annual-report/2026/56809935/', '2026-06-30'::date, NOW()),
  ('NXG', 'NexGen Energy Ltd.', 'Uranium', 'Canada', 'Developer / construction licensed', NULL, 9.98, 257, 240, NULL, NULL, NULL, NULL, 2237400000, NULL, 5, 3, 2, 4, 'Rook I/Arrow fields use uranium lb units despite the app label saying Moz/oz. Resource/reserve and cost trend update are company-reported; capex uses the 2024 trend estimate of approximately C$2.2B converted at ~C$1=A$1.017. Environmental assessment approval and construction licence were received in March 2026, but full funding/execution remains the main risk. NPV/IRR left blank until the current project economics table is captured directly.', 'https://www.sec.gov/Archives/edgar/data/1698535/000106299326002332/exhibit99-2.htm', '2026-03-31'::date, NOW()),
  ('PAAS', 'Pan American Silver Corp.', 'Silver / gold', 'Canada, Mexico, Peru, Bolivia, Argentina, Brazil, Chile, Guatemala', 'Producer', NULL, 17.8, NULL, NULL, 2521080000, 1177904600, NULL, NULL, NULL, NULL, 3, 4, 4, 4, 'Q2 2026 silver-segment AISC, cash/short-term investments and total debt are company-reported and converted at ~US$1=A$1.40 where applicable. Production and reserve/resource fields left blank pending direct capture from the 2025 annual report/reserve statement. Main risk is multi-jurisdiction operating and political exposure despite strong liquidity.', 'https://panamericansilver.com/news/pan-american-silver-reports-second-quarter-2026-financial-results/', '2026-06-30'::date, NOW()),
  ('PDN', 'Paladin Energy Ltd.', 'Uranium', 'Namibia, Canada, Australia', 'Producer / ramp-up complete', 4820000, 43.3, 122, 77.5, NULL, NULL, NULL, NULL, NULL, NULL, 4, 3, 3, 3, 'FY2026 Langer Heinrich production and cost of production use uranium lb units despite the app label saying oz; cost field is US$/lb cost of production, not full AISC. Resource and reserve fields use 30 Jun 2025 Langer Heinrich 100% basis Mlb U3O8. Cash/debt left blank until FY2026 financial statements are captured directly.', 'https://www.globenewswire.com/news-release/2026/07/22/3331046/0/en/Paladin-Energy-Ltd-Quarterly-Report-for-the-period-ending-30-June-2026.html', '2026-06-30'::date, NOW()),
  ('RRL', 'Regis Resources Limited', 'Gold', 'Australia', 'Producer', 379050, 2103, NULL, NULL, 1184000000, NULL, NULL, NULL, NULL, NULL, 5, 5, 4, 4, 'FY2026 gold production, AISC and cash/bullion are company-reported. AISC was reported in A$/oz and converted to US$/oz at ~US$1=A$1.40 for the app field. Reserve/resource fields are left blank until the FY2026 annual reserve table is captured directly.', 'https://financialfilings.com/filings/regis-resources-limited/earnings-release/2026/57059685/', '2026-06-30'::date, NOW()),
  ('SIL', 'Global X Silver Miners ETF', 'Silver miners ETF', 'Global', 'ETF', NULL, NULL, NULL, NULL, NULL, NULL, 6904958000, NULL, NULL, NULL, 3, 3, 4, 4, 'ETF record: operating mine economics do not apply at fund level. Market cap field is used as AUM, converted from US$4.93B at ~US$1=A$1.40. Top holdings included Wheaton, Pan American, Coeur, Hecla and First Majestic. Scores reflect diversified fund structure and concentrated silver-miner beta, not a single issuer.', 'https://www.globalxetfs.com/funds/sil?source_caller=ui', '2026-08-12'::date, NOW()),
  ('SILJ', 'Amplify Junior Silver Miners ETF', 'Junior silver miners ETF', 'Global', 'ETF', NULL, NULL, NULL, NULL, NULL, NULL, 5836270391, NULL, NULL, NULL, 3, 2, 3, 4, 'ETF record: operating mine economics do not apply at fund level. Market cap field is used as AUM, converted from US$4.167B at ~US$1=A$1.40. Top holdings included Hecla, First Majestic, SSR Mining, Wheaton, Endeavour Silver and Aya. Higher risk scores reflect small/mid-cap silver beta and single-theme concentration.', 'https://amplifyetfs.com/silj/', '2026-08-19'::date, NOW()),
  ('SVM', 'Silvercorp Metals Inc.', 'Silver / lead / zinc / gold', 'China, Ecuador', 'Producer / development', 6800000, 14.25, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, 4, 3, 4, 'FY2026 silver production and AISC are company-reported from the fiscal year ended 31 Mar 2026. Resource/reserve and balance-sheet fields left blank until the annual reserve and financial tables are captured directly. Jurisdiction score reflects China operating exposure despite strong reported cost performance.', 'https://www.sec.gov/Archives/edgar/data/1340677/000110465926066826/tm2615713d1_ex99-4.htm', '2026-03-31'::date, NOW()),
  ('URNM', 'BetaShares Global Uranium ETF', 'Uranium equities / physical uranium ETF', 'Global', 'ETF', NULL, NULL, NULL, NULL, NULL, NULL, 334623559, NULL, NULL, NULL, 3, 2, 3, 4, 'ETF record: mine economics do not apply at fund level. Market cap field is used as AUM. Top holdings included Kazatomprom, Cameco, Sprott Physical Uranium Trust, Paladin, NexGen, Denison, Deep Yellow, Uranium Energy, Yellow Cake and Energy Fuels. Scores reflect concentrated uranium-cycle and regulatory risk at portfolio level.', 'https://www.betashares.com.au/fund/global-uranium-etf/', '2026-08-20'::date, NOW()),
  ('UUUU', 'Energy Fuels Inc.', 'Uranium / rare earths', 'United States, Australia, Brazil', 'Producer / processor / development', 310000, NULL, NULL, NULL, 81795040, NULL, NULL, NULL, NULL, NULL, 5, 4, 3, 3, 'Production field uses Q2 2026 uranium pounds sold, not annual production, because that was the directly sourced current operating metric. Cash is cash/equivalents only; source also reports nearly US$1B working capital including marketable securities and inventory. Debt/resource/reserve fields left blank pending direct capture from annual property tables.', 'https://investors.energyfuels.com/2026-08-05-Energy-Fuels-Announces-Q2-2026-Results', '2026-06-30'::date, NOW()),
  ('VAU', 'Vault Minerals Limited', 'Gold', 'Australia', 'Producer / merger pending', 336540, 2088, 6.022, 2.238, 841600000, 0, NULL, NULL, NULL, NULL, 5, 5, 4, 4, 'FY2026 production, AISC, cash/bullion and no-debt status are reported from the June 2026 quarter coverage; AISC was reported in A$/oz and converted to US$/oz at ~US$1=A$1.40. Resource/reserve fields use Leonora operations data from the company operations page. Pending Genesis merger is the main corporate-action watch item.', 'https://www.vaultminerals.com/operations/leonora-operations', '2026-06-30'::date, NOW()),
  ('WRN', 'Western Copper and Gold Corporation', 'Copper / gold / molybdenum / silver', 'Yukon, Canada', 'Developer / environmental assessment', 259000, NULL, 21.1, 8.5, 137295000, NULL, NULL, 2373678000, 3679506000, 18.1, 4, 3, 2, 3, 'Production field is average annual gold production from the 2022 Casino feasibility snapshot; the project is primarily copper-gold, so copper/moly output is captured in notes rather than app fields. Resource field combines M&I and inferred gold resources; reserve field uses mill gold reserve ounces only. NPV8 and capex are C$ after-tax/capital figures converted at ~C$1=A$1.017. Very large capex versus current treasury means financing/dilution risk remains high.', 'https://www.westerncopperandgold.com/casino-project/', '2026-03-31'::date, NOW())
